-- Apply to a NEW Supabase project. Review before production use.
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique not null check(username ~ '^[a-z0-9_]{3,30}$'),display_name text not null default '',bio text not null default '',avatar_path text,is_private boolean not null default false,created_at timestamptz not null default now());
create table public.events(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id),title text not null check(length(title) between 1 and 120),event_date timestamptz,privacy text not null default 'private' check(privacy in ('private','public')),created_at timestamptz not null default now());
create table public.event_members(event_id uuid references public.events(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,role text not null default 'guest' check(role in ('guest','editor')),status text not null default 'invited' check(status in ('invited','accepted')),created_at timestamptz not null default now(),primary key(event_id,user_id));
create function public.can_view_event(e uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.events x where x.id=e and (x.owner_id=(select auth.uid()) or x.privacy='public' or exists(select 1 from public.event_members m where m.event_id=x.id and m.user_id=(select auth.uid()) and m.status='accepted')))$$;
create table public.posts(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),event_id uuid references public.events(id),caption text not null default '' check(length(caption)<=2200),kind text not null default 'text' check(kind in ('text','image','video')),media_path text,created_at timestamptz not null default now());
create table public.post_likes(post_id uuid references public.posts(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create table public.saved_posts(post_id uuid references public.posts(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create table public.post_comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,user_id uuid not null references public.profiles(id),body text not null check(length(body) between 1 and 1000),created_at timestamptz not null default now());
create table public.follows(follower_id uuid references public.profiles(id) on delete cascade,following_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(follower_id,following_id),check(follower_id<>following_id));
create table public.stories(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),media_path text not null,expires_at timestamptz not null default(now()+interval '24 hours'),created_at timestamptz not null default now());
create table public.conversations(id uuid primary key default gen_random_uuid(),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create table public.conversation_members(conversation_id uuid references public.conversations(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(conversation_id,user_id));
create function public.in_chat(c uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.conversation_members cm where cm.conversation_id=c and cm.user_id=(select auth.uid()))$$;
create table public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references public.profiles(id),body text not null check(length(body) between 1 and 4000),created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),actor_id uuid references public.profiles(id),kind text not null,body text not null default '',read boolean not null default false,created_at timestamptz not null default now());
create table public.event_media(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id) on delete cascade,user_id uuid not null references public.profiles(id),storage_path text not null,created_at timestamptz not null default now());
create table public.invitations(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id) on delete cascade,owner_id uuid not null references public.profiles(id),design jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.support_tickets(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),subject text not null check(length(subject) between 1 and 150),body text not null check(length(body) between 1 and 5000),created_at timestamptz not null default now());
create function public.can_view_post(p uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.posts x join public.profiles a on a.id=x.user_id where x.id=p and (x.user_id=(select auth.uid()) or (x.event_id is not null and public.can_view_event(x.event_id)) or (x.event_id is null and (not a.is_private or exists(select 1 from public.follows f where f.follower_id=(select auth.uid()) and f.following_id=a.id)))))$$;
create function public.new_profile() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,username,display_name) values(new.id,'user_'||substr(replace(new.id::text,'-',''),1,16),coalesce(new.raw_user_meta_data->>'name',''));return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.new_profile();
-- Existing auth users must be backfilled before use.
DO $$declare t text;begin foreach t in array array['profiles','events','event_members','posts','post_likes','saved_posts','post_comments','follows','stories','conversations','conversation_members','messages','notifications','event_media','invitations','support_tickets'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy profile_read on public.profiles for select to authenticated using(true);
create policy profile_update on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy events_read on public.events for select to authenticated using(public.can_view_event(id));
create policy events_insert on public.events for insert to authenticated with check(owner_id=(select auth.uid()));
create policy events_update on public.events for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
create policy events_delete on public.events for delete to authenticated using(owner_id=(select auth.uid()));
create policy members_read on public.event_members for select to authenticated using(user_id=(select auth.uid()) or public.can_view_event(event_id));
create policy members_insert on public.event_members for insert to authenticated with check(exists(select 1 from public.events e where e.id=event_id and e.owner_id=(select auth.uid())));
create policy members_update on public.event_members for update to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.events e where e.id=event_id and e.owner_id=(select auth.uid()))) with check(user_id=(select auth.uid()) or exists(select 1 from public.events e where e.id=event_id and e.owner_id=(select auth.uid())));
create policy members_delete on public.event_members for delete to authenticated using(exists(select 1 from public.events e where e.id=event_id and e.owner_id=(select auth.uid())));
create policy posts_read on public.posts for select to authenticated using(public.can_view_post(id));
create policy posts_insert on public.posts for insert to authenticated with check(user_id=(select auth.uid()) and (event_id is null or public.can_view_event(event_id)));
create policy posts_delete on public.posts for delete to authenticated using(user_id=(select auth.uid()));
create policy likes_read on public.post_likes for select to authenticated using(public.can_view_post(post_id));
create policy likes_insert on public.post_likes for insert to authenticated with check(user_id=(select auth.uid()) and public.can_view_post(post_id));
create policy likes_delete on public.post_likes for delete to authenticated using(user_id=(select auth.uid()));
create policy saved_read on public.saved_posts for select to authenticated using(user_id=(select auth.uid()));
create policy saved_insert on public.saved_posts for insert to authenticated with check(user_id=(select auth.uid()) and public.can_view_post(post_id));
create policy saved_delete on public.saved_posts for delete to authenticated using(user_id=(select auth.uid()));
create policy comments_read on public.post_comments for select to authenticated using(public.can_view_post(post_id));
create policy comments_insert on public.post_comments for insert to authenticated with check(user_id=(select auth.uid()) and public.can_view_post(post_id));
create policy comments_delete on public.post_comments for delete to authenticated using(user_id=(select auth.uid()));
create policy follows_read on public.follows for select to authenticated using(true);
create policy follows_insert on public.follows for insert to authenticated with check(follower_id=(select auth.uid()));
create policy follows_delete on public.follows for delete to authenticated using(follower_id=(select auth.uid()));
create policy stories_read on public.stories for select to authenticated using(expires_at>now() and (user_id=(select auth.uid()) or exists(select 1 from public.profiles p where p.id=user_id and not p.is_private) or exists(select 1 from public.follows f where f.following_id=user_id and f.follower_id=(select auth.uid()))));
create policy stories_insert on public.stories for insert to authenticated with check(user_id=(select auth.uid()) and expires_at<=now()+interval '24 hours');
create policy stories_delete on public.stories for delete to authenticated using(user_id=(select auth.uid()));
create policy chat_read on public.conversations for select to authenticated using(public.in_chat(id));
create policy chat_insert on public.conversations for insert to authenticated with check(created_by=(select auth.uid()));
create policy chat_members_read on public.conversation_members for select to authenticated using(public.in_chat(conversation_id));
create policy chat_members_insert on public.conversation_members for insert to authenticated with check(exists(select 1 from public.conversations c where c.id=conversation_id and c.created_by=(select auth.uid())));
create policy messages_read on public.messages for select to authenticated using(public.in_chat(conversation_id));
create policy messages_insert on public.messages for insert to authenticated with check(sender_id=(select auth.uid()) and public.in_chat(conversation_id));
create policy notif_read on public.notifications for select to authenticated using(user_id=(select auth.uid()));
create policy notif_update on public.notifications for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy media_read on public.event_media for select to authenticated using(public.can_view_event(event_id));
create policy media_insert on public.event_media for insert to authenticated with check(user_id=(select auth.uid()) and public.can_view_event(event_id));
create policy media_delete on public.event_media for delete to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.events e where e.id=event_id and e.owner_id=(select auth.uid())));
create policy invite_read on public.invitations for select to authenticated using(public.can_view_event(event_id));
create policy invite_insert on public.invitations for insert to authenticated with check(owner_id=(select auth.uid()) and exists(select 1 from public.events e where e.id=event_id and e.owner_id=(select auth.uid())));
create policy invite_update on public.invitations for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
create policy tickets_read on public.support_tickets for select to authenticated using(user_id=(select auth.uid()));
create policy tickets_insert on public.support_tickets for insert to authenticated with check(user_id=(select auth.uid()));
-- Private buckets; never expose service role key.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('social-media','social-media',false,104857600,array['image/jpeg','image/png','image/webp','video/mp4','video/webm']),('event-private','event-private',false,15728640,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy social_storage_read on storage.objects for select to authenticated using(bucket_id='social-media' and (exists(select 1 from public.posts p where p.media_path=name and public.can_view_post(p.id)) or exists(select 1 from public.stories s where s.media_path=name and s.expires_at>now() and (s.user_id=(select auth.uid()) or exists(select 1 from public.profiles pr where pr.id=s.user_id and not pr.is_private)))));
create policy social_storage_upload on storage.objects for insert to authenticated with check(bucket_id='social-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy social_storage_delete on storage.objects for delete to authenticated using(bucket_id='social-media' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy event_storage_read on storage.objects for select to authenticated using(bucket_id='event-private' and exists(select 1 from public.event_media em where em.storage_path=name and public.can_view_event(em.event_id)));
create policy event_storage_upload on storage.objects for insert to authenticated with check(bucket_id='event-private' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy event_storage_delete on storage.objects for delete to authenticated using(bucket_id='event-private' and (storage.foldername(name))[1]=(select auth.uid())::text);
create index posts_recent on public.posts(created_at desc);create index messages_by_chat on public.messages(conversation_id,created_at);create index stories_expiry on public.stories(expires_at);create index notifications_by_user on public.notifications(user_id,created_at desc);
